import csv
import io

from .errors import LedgerError


def open_table(path, required, code):
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        raise LedgerError(code, f"{path}: cannot read file") from None
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise LedgerError(code, f"{path}: not valid UTF-8") from None

    reader = csv.reader(io.StringIO(text, newline=""))
    try:
        header = next(reader, None)
    except csv.Error:
        raise LedgerError(code, f"{path}:{reader.line_num}: malformed CSV") from None
    if header is None:
        raise LedgerError(code, f"{path}: missing header")

    names = [h.strip().lower() for h in header]
    seen = set()
    for n in names:
        if n in seen:
            raise LedgerError(code, f"{path}: duplicate column '{n}'")
        seen.add(n)
    for r in required:
        if r not in seen:
            raise LedgerError(code, f"{path}: missing column '{r}'")

    width = len(header)

    def rows():
        while True:
            try:
                rec = next(reader, None)
            except csv.Error:
                raise LedgerError(
                    code, f"{path}:{reader.line_num}: malformed CSV"
                ) from None
            if rec is None:
                return
            if rec == []:
                continue
            line = reader.line_num
            if len(rec) != width:
                raise LedgerError(
                    code, f"{path}:{line}: expected {width} fields, got {len(rec)}"
                )
            yield line, rec

    return names, rows()
